def check_round_status(n, ratings):
    sorted_ratings = sorted(ratings, key=lambda x: (-x[1], x[0]))
    original_positions = {rating[0]: i for i, rating in enumerate(ratings)}
    new_positions = {sorted_rating[0]: i for i, sorted_rating in enumerate(sorted_ratings)}

    changed = False
    for user_id in ratings:
        if original_positions[user_id] != new_positions[user_id]:
            changed = True
            break

    if not changed:
        return "unrated"

    for i in range(1, n):
        if ratings[i][1] > ratings[i - 1][1] and new_positions[ratings[i][0]] < new_positions[ratings[i - 1][0]]:
            return "rated"

    return "maybe"

